  'Use = or := to define, e.g. a = 5 or f(x) := x^2 + 1. Use e for Euler’s number and i for √−1.': '用 = 或 := 定義，例如 a = 5 或 f(x) := x^2 + 1。e 代表歐拉數，i 代表 √−1。',
