  'Notes': '備註',
  'Tabular classification': '表格資料分類',
  'Boosted trees win most tabular benchmarks. Scale features only for linear, SVM, KNN, and neural models.': '提升樹在大多數表格資料基準測試中表現最佳。僅對線性模型、SVM、KNN 和神經網路做特徵縮放。',
  'Tabular regression': '表格資料迴歸',
  'Check the target distribution; try `log1p` on skewed positive targets.': '檢查目標變數的分佈；對偏斜的正值目標可嘗試 `log1p`。',
  'Many categoricals': '類別變數很多',
  '`CatBoostClassifier` with `cat_features`': '指定 `cat_features` 的 `CatBoostClassifier`',
  'CatBoost handles high-cardinality categories natively.': 'CatBoost 可原生處理高基數類別。',
  'Small dataset (< 1k rows)': '小資料集（少於 1k 列）',
  'Use repeated stratified CV; avoid heavy tuning.': '使用重複分層交叉驗證；避免過度調參。',
  'Text (bag of words)': '文字（詞袋）',
  'Sparse linear models are fast and hard to beat on TF-IDF.': '稀疏線性模型速度快，在 TF-IDF 上很難被超越。',
  'Scale first. Density methods find non-convex clusters and noise.': '先做縮放。基於密度的方法可以找出非凸叢集和雜訊點。',
