  'Estimator API': 'Estimator API',
  'Every scikit-learn object shares the same methods. XGBoost, LightGBM, and CatBoost follow the same API through their sklearn wrappers.': '所有 scikit-learn 物件共用相同的方法。XGBoost、LightGBM 和 CatBoost 透過其 sklearn 包裝器遵循相同的 API。',
