  'Linear models, SVM': '線性模型、SVM',
  'Use for ROC AUC when no probabilities.': '沒有機率時用於計算 ROC AUC。',
  'Transformers': '轉換器',
  'Only on training data. Use `transform` on validation and test.': '僅用於訓練資料；對驗證集和測試集使用 `transform`。',
  'Accuracy for classifiers, R² for regressors.': '分類器回傳準確率，迴歸器回傳 R²。',
  'Pipeline params use `step__param`.': 'Pipeline 參數使用 `step__param` 指定。',
