  '`Trainer(...).train()` with `load_best_model_at_end=True`': '`Trainer(...).train()` 並設定 `load_best_model_at_end=True`',
  'Use `fp16`/`bf16` on GPU.': '在 GPU 上使用 `fp16`/`bf16`。',
  '6. Evaluate': '6. 評估',
  '`compute_metrics` returns accuracy / F1 per epoch': '`compute_metrics` 每個 epoch 回傳準確率 / F1',
  '7. Test + save': '7. 測試 + 儲存',
  '`trainer.predict(test)`; `save_pretrained` model and tokenizer': '`trainer.predict(test)`；用 `save_pretrained` 儲存模型和 tokenizer',
  'Trainer fine-tuning': '用 Trainer fine-tune',
  'SOP: Neural network for tabular data': 'SOP：表格資料的神經網路',
  'An MLP with categorical embeddings: the usual deep baseline for tables.': '帶類別 embedding 的 MLP：表格資料常用的深度學習 baseline。',
  'Large tables, multi-task outputs, or when the model must be combined with images/text. Boosted trees usually win on small tables.': '大型表格、多工輸出，或需要與影像 / 文字結合時。小表格上通常提升樹更優。',
  'Scale numerics': '縮放數值特徵',
  'Embed categoricals': 'embedding 類別變數',
  'MLP': 'MLP',
  'AdamW + OneCycle': 'AdamW + OneCycle',
  'Early stop': 'early stopping',
  'Compare with GBM': '與 GBM 比較',
  'Same splits as your GBM baseline': '使用與 GBM baseline 相同的切分',
  'So the comparison is fair.': '這樣比較才公平。',
  '2. Numerics': '2. 數值',
  'Impute, then `StandardScaler` or `QuantileTransformer(output_distribution="normal")` (fit on train)': '先填補缺失值，再用 `StandardScaler` 或 `QuantileTransformer(output_distribution="normal")`（在訓練集上 fit）',
  'Unscaled inputs make training unstable.': '未縮放的輸入會讓訓練不穩定。',
  '3. Categoricals': '3. 類別變數',
  'Map to ids (reserve 0 for unknown), `nn.Embedding(n, min(50, (n + 1) // 2))`': '映射為 id（0 保留給未知類別），`nn.Embedding(n, min(50, (n + 1) // 2))`',
  '4. Model': '4. 模型',
  '2–4 Linear layers of 128–512, BatchNorm/LayerNorm, ReLU/SiLU, Dropout 0.1–0.3': '2–4 層 128–512 寬度的 Linear，BatchNorm/LayerNorm，ReLU/SiLU，Dropout 0.1–0.3',
  '5. Optimize': '5. 最佳化',
  '`AdamW`, `OneCycleLR(max_lr=1e-3…3e-3)`, batch 256–1024': '`AdamW`、`OneCycleLR(max_lr=1e-3…3e-3)`，batch 256–1024',
  'Patience 10–20 epochs on valid metric': '以驗證指標為準，patience 取 10–20 個 epoch',
  '7. Compare': '7. 比較',
  'Against LightGBM / CatBoost; try averaging both': '與 LightGBM / CatBoost 比較；也可嘗試兩者取平均',
