  'LogSoftmax + NLLLoss in one. Input: raw logits (N, C); target: class ids (N,) or class probabilities (N, C).': 'LogSoftmax + NLLLoss 合二為一。輸入：原始 logits (N, C)；目標：類別 id (N,) 或類別機率 (N, C)。',
