  'Match shapes: `pred.squeeze(-1)` vs target (N,) — broadcasting (N,1) vs (N,) silently gives the wrong loss.': '注意形狀匹配：`pred.squeeze(-1)` 對應目標 (N,)——(N,1) 與 (N,) 的廣播會悄悄給出錯誤的 loss。',
